import{_ as a,C as s,o as r,c as n,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const p="/screenshots/desktop-run-live.png",y=JSON.parse(`{"title":"Desktop app runs","description":"Pause, step and watch the Playwright runs the desktop app starts, from its Local runs tray: each worker's test, the page at a stop, live, a pick on its image, the code a stop makes, to copy, a run shared live with your team, and the same runs for a coding agent.","frontmatter":{"title":"Desktop app runs","description":"Pause, step and watch the Playwright runs the desktop app starts, from its Local runs tray: each worker's test, the page at a stop, live, a pick on its image, the code a stop makes, to copy, a run shared live with your team, and the same runs for a coding agent.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/desktop-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/desktop-runs.html"}],["meta",{"property":"og:title","content":"Desktop app runs | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Pause, step and watch the Playwright runs the desktop app starts, from its Local runs tray: each worker's test, the page at a stop, live, a pick on its image, the code a stop makes, to copy, a run shared live with your team, and the same runs for a coding agent."}]]},"headers":[],"relativePath":"features/desktop-runs.md","filePath":"features/desktop-runs.md","lastUpdated":1793258669000}`),c={name:"features/desktop-runs.md"};function l(u,e,g,w,f,m){const o=s("Needs");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"desktop-app-runs",tabindex:"-1"},[i("Desktop app runs "),t("a",{class:"header-anchor",href:"#desktop-app-runs","aria-label":'Permalink to "Desktop app runs"'},"​")],-1)),h(o,{desktop:"",fixtures:""}),e[1]||(e[1]=d('<p>Every Playwright run the <a href="./desktop.html">desktop app</a> starts names the app as its hub: <strong>Run locally</strong>, a reproduction, a bisect step, a <a href="./flake-lab.html">Flake Lab</a> run and a bug report&#39;s run. Its <strong>Local runs</strong> tray shows each worker of the run beside its output, and steers the test as the editor does: <a href="./editor-run-control.html">Pause and step from the editor</a>. Nothing leaves your machine unless you <a href="#share-live">share a run live</a>.</p><h2 id="each-worker" tabindex="-1">Each worker <a class="header-anchor" href="#each-worker" aria-label="Permalink to &quot;Each worker&quot;">​</a></h2><p>While a run goes on, the tray shows each worker&#39;s test, its Playwright project and its attempt, and whether it runs. <strong>Pause</strong> stops the test before its next call that acts on or checks the page. A test also stops at a <code>page.pause()</code>, and a headed one shows Piwi&#39;s <a href="./editor-breakpoints.html#pause-a-run">pause bar</a> there.</p><p>At a stop, the tray says why the test stopped, the call about to run and its place in your code, with an image of the page. <strong>Resume</strong> lets the test go on, <strong>Step</strong> runs one call and stops before the next, <strong>Finish</strong> runs the test to its end without stopping again, and <a href="./end-the-test.html"><strong>End the test</strong></a> skips the rest of it.</p><p><strong>Hold failures</strong>, on each running run in the tray, holds a failing test at its line: <strong>Failed at</strong>, its error under it, and <strong>Resume</strong> to let it end as it failed. It is off for a run you start, and on from the start for <strong>Reproduce</strong>, which runs to show you the failure; while <a href="./runs-window.html">Piwi Picker&#39;s Runs window</a> is open, failures are held too. A run nobody attends never holds one, and its switch says so: a Flake Lab run, a bisect, a lab job, a run with <code>--repeat-each</code> above 1 and UI mode go on past each failure.</p><figure><img src="'+p+'" alt="The Local runs tray of the desktop app: a running run with its Hold failures switch, and its checkout test stopped at its page.pause() before its click on Pay now, its page watched live, with Resume, Step, Finish, Assert a region and Mock a request"><figcaption>A run the desktop app started, stopped at a <code>page.pause()</code> and watched live.</figcaption></figure><p>The tray opens at each stop: a headless test waits for you there. While the window is in the background, the system tells you of a failure or a <code>page.pause()</code>, never of a step or a pause you asked for. When no run of the app is going on, the window stops listening, and a stop goes on at once.</p><h2 id="watch-live" tabindex="-1">Watch live <a class="header-anchor" href="#watch-live" aria-label="Permalink to &quot;Watch live&quot;">​</a></h2><p><strong>Watch live</strong> shows the stopped page as it paints, in place of its image, and stays on for the worker&#39;s next stops until you turn it off. Your clicks, the wheel and your keys on the view go to the page. <code>Esc</code> gives the keyboard back to the tray, and <code>Tab</code> leaves the view unless a click into it took the keyboard. The frames go from the test&#39;s worker to the windows that watch that stop, the app&#39;s and Piwi Picker&#39;s Runs window, and nothing keeps them.</p><p><strong>Pick on the image</strong>, or a <code>Shift</code>+click on the image or the view, names the element under the pointer: its locator shows under the test, with <strong>Copy</strong>.</p><h2 id="code-to-copy" tabindex="-1">Code to copy <a class="header-anchor" href="#code-to-copy" aria-label="Permalink to &quot;Code to copy&quot;">​</a></h2><p>The app holds no editor, so the code a stop makes comes to the tray, under <strong>Code from the runs</strong>, rather than into your file:</p><ul><li><strong>Assert a region</strong> picks a region of the page, once you watch a headless stop live: its ARIA snapshot becomes a <code>toMatchAriaSnapshot</code> check.</li><li><strong>Mock a request</strong> lists the page&#39;s fetch and XHR responses, credentials hidden: the one you choose becomes a <code>page.route</code>, with what to review in it.</li><li><strong>A locator picked</strong>, on the image or with the pause bar&#39;s <strong>Pick a locator</strong>, shows with the line it was picked for.</li></ul><p>Each code shows the line it goes above, and its import lines apart, each with <strong>Copy</strong>. The code is made from the file as it is on disk, in the folder linked to the project.</p><h2 id="share-live" tabindex="-1">Share live <a class="header-anchor" href="#share-live" aria-label="Permalink to &quot;Share live&quot;">​</a></h2><p>A run that reports to your team&#39;s Piwi instance, as a <strong>Run locally</strong> in a folder whose <code>.env</code> or Playwright config names it does, can be shared there for a teammate to watch from its page, in a project whose live view is on: <strong>Share live</strong>, above the run&#39;s workers, any time while it runs. The first time since the app started, it says what goes out and to whom, and waits for your yes. Shared, the run says where and how many views are open, with <strong>Copy the run page&#39;s link</strong> and <strong>Stop sharing</strong>. A run that cannot be shared says why: <a href="./live-view.html#share-a-run-from-your-machine">Share a run from your machine</a>.</p><p>A run that reports to the app itself (a reproduction, a bisect, a <strong>Run locally</strong> in a folder that names no instance) offers no <strong>Share live</strong>: the app hands out no live view key, since no teammate reaches it, and its project settings have no <strong>Live view</strong> section.</p><h2 id="from-piwi-picker" tabindex="-1">From Piwi Picker <a class="header-anchor" href="#from-piwi-picker" aria-label="Permalink to &quot;From Piwi Picker&quot;">​</a></h2><p>Paired with the app, <a href="./runs-window.html#the-desktop-app-s-runs">Piwi Picker&#39;s Runs window</a> lists its runs beside your editor&#39;s, steers them, and watches their pages live. Code it starts at a stop of the app&#39;s run comes to the app&#39;s tray too.</p><h2 id="for-agents" tabindex="-1">For agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to &quot;For agents&quot;">​</a></h2><p>The app&#39;s <a href="./mcp.html">MCP server</a>, which its <strong>MCP server</strong> page connects your coding agent to, serves these runs with the tools of <a href="./agent-run-control.html">Run control for agents</a>: <code>run_list</code>, <code>run_follow</code>, <code>run_control</code>, <code>page_snapshot</code>, <code>page_act</code>, <code>page_locator</code> and <code>code_write</code>. An agent follows a run, pauses or steps it, reads the stopped page as its ARIA snapshot and acts on it by ref, as you can and no further: a stopped page alone, the actions the tools name, no code to evaluate. What comes from the page reaches it marked as the page&#39;s, never as instructions.</p><p>What it does shows in the tray: a stop it asked for says so (<strong>Paused by the agent</strong>), and so does its first action at a stop. The code <code>code_write</code> makes (the steps it took, an assertion, or a locator for the stopped line) comes under <strong>Code from the runs</strong>, to copy, and back to the agent in its answer: no file is written. A run nobody attends is not served, so an agent sees no Flake Lab run, bisect or lab job.</p><p>An agent pauses, steps or runs to a line only while the app&#39;s window is open, in the tray included: a headless stop goes on with no window to show it. A stop it asked for goes on two minutes after its last call, so a run never waits for an agent that left.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>No recording.</strong> <strong>Record here</strong>, and <strong>Pick</strong> and <strong>Assert</strong> in the test&#39;s window, end in an editor: run the test from VS Code or a JetBrains IDE to use them.</li><li><strong>A linked folder.</strong> A reproduction or a bisect step runs in a throwaway worktree, which no project links: its stops make no code.</li><li><strong>A file changed since the run started</strong> makes no code: run the test again.</li><li><strong>Run to cursor</strong> stays in the editor, which has the file.</li><li><strong>One call at a time through the bridge.</strong> Claude Desktop reaches the app through <code>piwi-desktop mcp-stdio</code>, which passes its calls one by one: a <code>run_follow</code> or a <code>run_control</code> that waits holds the next call, 40 seconds at most (a 30-second wait, then the stopped page&#39;s snapshot).</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./desktop.html">Desktop app</a>: what it runs, and how it links a project to its folder.</li><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the same stops, in VS Code and the JetBrains IDEs.</li><li><a href="./editor-stop-code.html">Code from a pause</a>: what each action writes.</li><li><a href="./runs-window.html">Runs window</a>: Piwi Picker&#39;s window for the same runs.</li><li><a href="./agent-run-control.html">Run control for agents</a>: the tools an agent steers the runs with.</li></ul>',27))])}const b=a(c,[["render",l]]);export{y as __pageData,b as default};
